#!/usr/bin/env python3
"""Build an editable, evidence-linked PowerPoint skeleton using only Python stdlib."""
from pathlib import Path
from zipfile import ZipFile, ZIP_DEFLATED
from xml.sax.saxutils import escape
import json
import xml.etree.ElementTree as ET

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'submission'
SLIDES = [
('Robust bank account fraud detection', 8, 'A', ['Temporal drift, training history and class imbalance', 'BT4012 Fraud Analytics | Group XX', '[Insert all group members and student IDs]'], 'Introduce the title and group. Leave the title readable for eight seconds. Replace the placeholders before recording.', 'Project Guidelines, pp. 3–6'),
('The decision: which applications should be reviewed?', 42, 'A', ['One row is an account application, not a payment transaction.', 'Fraud is rare, review capacity is limited, and populations change over time.', 'We study a ranking and human-review pipeline; labels do not measure fraud prevented.'], 'Set the business context. Ask whether prioritising recent training data actually improves future detection, and distinguish modelling from intervention outcomes.', 'reports/baf-study-v1/findings.md'),
('Three questions drive the experiments', 50, 'A', ['Does recent history beat equally sized historical training data?', 'How do model family and class weighting affect detection?', 'Can feature engineering and ensembles improve useful operating points?'], 'Explain why a model leaderboard alone cannot answer the recency question. Each question has a controlled comparison; later improvement work is exploratory.', 'docs/experiment-protocol.md; docs/improvement-protocol.md'),
('BAF Base v2: rare fraud across eight months', 55, 'A', ['1,000,000 applications; 32 source columns; months 0–7.', '29 predictors after excluding target, split key and constant device_fraud_count.', 'Month 7: 96,843 applications and 1,428 fraud labels (1.47%).', 'Development prevalence changes from 0.87% to 1.34%; missingness uses encoded sentinels.'], 'Show the saved monthly prevalence figure when aesthetics are added. Explain synthetic data, monthly timing and why zero literal nulls does not mean complete observations.', 'reports/baf-study-v1/monthly.png; reports/baf-study-v1/findings.md'),
('Chronological evaluation keeps future scoring separate', 50, 'B', ['Train months 0–3 → validate 4; train 0–4 → validate 5; train 0–5 → validate 6.', 'Original final model trains 0–6 and scores month 7 after a selection freeze.', 'Fit imputers, encoders and scalers on each eligible training subset only.', 'Later month-7 comparisons are exploratory: the holdout has already been consumed.'], 'Use the chronological split diagram in the final design. Model selection uses development data; later threshold policies also learn only from earlier development months.', 'docs/experiment-protocol.md; reports/baf-improvements-v1/findings.md'),
('Match size and class counts to isolate recency', 55, 'B', ['K = 100,000; 250,000; 500,000.', 'Recent K: latest eligible months, with random selection at the boundary month.', 'Historical K: same K and exact fraud/nonfraud counts; seeds 17, 29 and 43.', 'All strategies predict identical future applications; expanding history is a separate size comparison.'], 'Historical controls may include recent observations. Do not call this recent-versus-oldest. There are no within-month timestamps, so row order is not treated as time.', 'docs/experiment-protocol.md; reports/baf-study-v1/validation_recency.csv'),
('Preprocessing follows the model', 50, 'B', ['All models: documented sentinel handling and training-only transformations.', 'Logistic regression: median imputation, missing indicators, scaling and one-hot categories.', 'Original LightGBM / random forest: imputation, indicators and one-hot categories; no scaling.', 'Improvement study: separately declared native-category and engineered-feature recipes.'], 'Explain the linear baseline and nonlinear tree comparators. Do not retroactively describe the original LightGBM as the later native-categorical pipeline.', 'docs/experiment-protocol.md; docs/improvement-protocol.md'),
('Metrics describe different operating decisions', 60, 'B', ['Average precision summarises ranking under class imbalance.', 'Exact 1% review: choose ceil(0.01 × N) rows using label-free score ordering.', 'F1 / F2 thresholds are learned on eligible development predictions.', 'F2 weights recall more heavily; its search imposes no review quota or precision floor.'], 'Explicitly distinguish fixed capacity, fixed threshold and retrospective recall-at-FPR. Weighted scores and ensemble margins are not claimed calibrated probabilities.', 'docs/experiment-protocol.md; reports/baf-bagged-anchor-fusion-v1/findings.md'),
('Result 1: no reliable general recency advantage', 60, 'C', ['Month-7 recent-minus-matched recall: logistic +0.09 percentage points.', 'Conditional 95% interval: −0.61 to +0.89 percentage points.', 'LightGBM difference: +0.14 points; interval −0.81 to +0.89 points.', 'Both intervals include zero; these settings do not establish a reliable recency advantage.'], 'Use final_recency.png in the designed deck. Explain conditional uncertainty: fixed fitted models, not all retraining or future-month uncertainty. Null evidence is not proof of exact equivalence.', 'reports/baf-study-v1/findings.md; reports/baf-study-v1/final_recency.png'),
('Result 2: weighting changes the trade-off', 60, 'C', ['At equal month-7 1% review: unweighted LightGBM recall 22.34%; balanced 21.64%.', 'Unweighted random forest: 21.08%; unweighted logistic regression: 19.40%.', 'Weighting raises default-0.5 recall, but changes score scale and false-positive burden.', 'Compare models under the same operating policy before claiming improvement.'], 'The original validation-selected candidate remains balanced LightGBM; the higher observed unweighted final result does not retroactively replace it. These are fixed presets, not universal model-family rankings.', 'reports/baf-study-v1/findings.md; reports/baf-study-v1/weighting_and_models.png'),
('Result 3: targeted features help the linear model', 60, 'C', ['Mean forward logistic AP: 0.1542 → 0.1674.', 'Recall at 1% review: 19.84% → 21.00%; precision: 24.14% → 25.55%.', 'A fixed-C diagnostic separates engineered-feature effects from regularisation changes.', 'Feature engineering is model-specific; gains should not be assumed for tree models.'], 'Show the saved improvement ablation figure later. This is averaged development evidence over months 4–6, not a direct comparison to month-7 AP.', 'reports/baf-improvements-v1/findings.md; reports/baf-improvements-v1/ablations.png'),
('Exploratory ensembles: small operational gains', 60, 'C', ['Capacity-selected 25% LightGBM / 75% CatBoost blend: 334 frauds caught versus 319.', 'Same 969 reviews: recall 23.39% versus 22.34%; precision 34.47% versus 32.92%.', '15 fewer missed frauds and 15 fewer legitimate applications reviewed at the same budget.', 'Month 7 was already consumed; this is exploratory evidence, not fresh confirmation.'], 'Do not mix the AP-selected 50/50 blend with the capacity-selected 25/75 blend. Explain that most fraud still remains outside the small review queue.', 'reports/baf-improvements-v1/findings.md; reports/baf-improvements-v1/exploratory_policies.csv'),
('Further F2 search did not deliver a clear final win', 60, 'D', ['Selected bagged-anchor fusion: development F2 0.330881 versus balanced 0.327802.', 'Consumed month-7 F2: fusion 0.372240 versus unweighted reference 0.376884.', 'The development winner remains the selected strategy; no retrospective winner replacement.', 'Additional model complexity and search do not guarantee better future detection.'], 'Distinguish original fixed-capacity study from later F2 optimisation. F2 results have different review loads; do not present them as a 1% capacity comparison. Unfinished context ablation is excluded.', 'reports/baf-bagged-anchor-fusion-v1/findings.md; reports/baf-shallow-catboost-v1/findings.md'),
('Business integration: a measured human-review queue', 55, 'D', ['Validate fields → score applications → apply a declared review policy → human investigation.', 'Record realised alert volume, precision, recall, missed fraud and legitimate cases flagged.', 'Monitor population/prevalence shifts and threshold drift; plan controlled retraining and fairness checks.', 'Human review and outcome logging are proposed deployment steps, not evaluated interventions.'], 'Use exact capacity if operational budget is fixed. Fixed score thresholds may create variable review volume. The dataset lacks realised investigation cost, label delays and monetary losses, so do not claim savings.', 'docs/experiment-protocol.md; reports/baf-improvements-v1/findings.md'),
('Conclusion and limits', 45, 'D', ['Retain history unless controlled forward evidence supports a recency benefit.', 'Choose preprocessing and operating policies to match the model and review objective.', 'Useful improvements are modest; strong simple references remain essential.', 'Synthetic data, eight months, unknown label delays and adaptive search limit generalisation.'], 'Add the fixed-model bootstrap and consumed-holdout caveats verbally. New independent data are needed to confirm future performance. Complete member review and verify the reproducible code bundle before submission.', 'reports/baf-study-v1/findings.md; reports/baf-improvements-v1/findings.md'),
('Sources, reproducibility and acknowledgement', 20, 'D', ['Data: Jesus et al. (2022), Bank Account Fraud Dataset Suite, NeurIPS Datasets and Benchmarks.', 'Repository: github.com/snatzehua/bt-4012-project-2026', 'Protocols, configurations and checked results accompany the code; see submission-code-guide.md.', 'ChatGPT/Codex assisted with design, code, audits and writing; all submitted work requires group review.'], 'Mention any external branch material actually adopted in the final version and its assistance attribution. Replace the group placeholders; keep the references slide available after the conclusion.', 'README.md; docs/submission-code-guide.md')
]
# The source name for the size comparison is given in the findings; only link existing files.
SLIDES[5] = (*SLIDES[5][0:5], 'docs/experiment-protocol.md; reports/baf-study-v1/findings.md')
NSP='http://schemas.openxmlformats.org/presentationml/2006/main'; NSA='http://schemas.openxmlformats.org/drawingml/2006/main'; NSR='http://schemas.openxmlformats.org/officeDocument/2006/relationships'
H=f'xmlns:a="{NSA}" xmlns:r="{NSR}" xmlns:p="{NSP}"'
XML='<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
def rels(items):
 return XML+'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'+''.join(f'<Relationship Id="{i}" Type="{NSR}/{t}" Target="{target}"/>' for i,t,target in items)+'</Relationships>'
def txt(shapeid,x,y,w,h,lines,size=2400,bold=False,color='172B4D'):
 paras=''.join(f'<a:p><a:pPr marL="0" indent="0"><a:spcAft><a:spcPts val="1200"/></a:spcAft></a:pPr><a:r><a:rPr lang="en-GB" sz="{size}" b="{int(bold)}"><a:solidFill><a:srgbClr val="{color}"/></a:solidFill><a:latin typeface="Aptos"/></a:rPr><a:t>{escape(s)}</a:t></a:r><a:endParaRPr lang="en-GB"/></a:p>' for s in lines)
 return f'<p:sp><p:nvSpPr><p:cNvPr id="{shapeid}" name="Text {shapeid}"/><p:cNvSpPr txBox="1"/><p:nvPr/></p:nvSpPr><p:spPr><a:xfrm><a:off x="{x}" y="{y}"/><a:ext cx="{w}" cy="{h}"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom><a:noFill/><a:ln><a:noFill/></a:ln></p:spPr><p:txBody><a:bodyPr wrap="square" lIns="0" tIns="0" rIns="0" bIns="0"/><a:lstStyle/>{paras}</p:txBody></p:sp>'
def group(): return '<p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr><p:grpSpPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="0" cy="0"/><a:chOff x="0" y="0"/><a:chExt cx="0" cy="0"/></a:xfrm></p:grpSpPr>'
def build():
 OUT.mkdir(exist_ok=True)
 ppt=OUT/'presentationXX-skeleton.pptx'
 ct=['<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>','<Default Extension="xml" ContentType="application/xml"/>']
 def override(p,t): ct.append(f'<Override PartName="/{p}" ContentType="application/vnd.openxmlformats-officedocument.presentationml.{t}+xml"/>')
 parts={}
 parts['_rels/.rels']=rels([('rId1','officeDocument','ppt/presentation.xml')])
 parts['ppt/presentation.xml']=XML+f'<p:presentation {H}><p:sldMasterIdLst><p:sldMasterId id="2147483648" r:id="rId1"/></p:sldMasterIdLst><p:sldIdLst>'+''.join(f'<p:sldId id="{256+i}" r:id="rId{i+2}"/>' for i in range(len(SLIDES)))+'</p:sldIdLst><p:sldSz cx="12192000" cy="6858000"/><p:notesSz cx="6858000" cy="9144000"/></p:presentation>'
 override('ppt/presentation.xml','presentation.main')
 parts['ppt/_rels/presentation.xml.rels']=rels([('rId1','slideMaster','slideMasters/slideMaster1.xml')]+[(f'rId{i+2}','slide',f'slides/slide{i+1}.xml') for i in range(len(SLIDES))])
 parts['ppt/slideMasters/slideMaster1.xml']=XML+f'<p:sldMaster {H}><p:cSld name="Submission skeleton"><p:spTree>{group()}</p:spTree></p:cSld><p:clrMap accent1="accent1" accent2="accent2" accent3="accent3" accent4="accent4" accent5="accent5" accent6="accent6" bg1="lt1" bg2="lt2" folHlink="folHlink" hlink="hlink" tx1="dk1" tx2="dk2"/><p:sldLayoutIdLst><p:sldLayoutId id="2147483649" r:id="rId1"/></p:sldLayoutIdLst><p:txStyles><p:titleStyle/><p:bodyStyle/><p:otherStyle/></p:txStyles></p:sldMaster>'
 override('ppt/slideMasters/slideMaster1.xml','slideMaster')
 parts['ppt/slideMasters/_rels/slideMaster1.xml.rels']=rels([('rId1','slideLayout','../slideLayouts/slideLayout1.xml'),('rId2','theme','../theme/theme1.xml')])
 parts['ppt/slideLayouts/slideLayout1.xml']=XML+f'<p:sldLayout {H} type="blank" preserve="1"><p:cSld name="Blank"><p:spTree>{group()}</p:spTree></p:cSld><p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:sldLayout>'
 override('ppt/slideLayouts/slideLayout1.xml','slideLayout')
 parts['ppt/slideLayouts/_rels/slideLayout1.xml.rels']=rels([('rId1','slideMaster','../slideMasters/slideMaster1.xml')])
 scheme=''.join(f'<a:{k}><a:srgbClr val="{v}"/></a:{k}>' for k,v in [('dk1','172B4D'),('lt1','FFFFFF'),('dk2','334E68'),('lt2','F4F7FA'),('accent1','176B87'),('accent2','52A7A0'),('accent3','A67C52'),('accent4','8B6CA8'),('accent5','6585A8'),('accent6','C28E5C'),('hlink','0563C1'),('folHlink','954F72')])
 parts['ppt/theme/theme1.xml']=XML+f'<a:theme xmlns:a="{NSA}" name="BT4012"><a:themeElements><a:clrScheme name="BT4012">{scheme}</a:clrScheme><a:fontScheme name="Aptos"><a:majorFont><a:latin typeface="Aptos"/><a:ea typeface=""/><a:cs typeface=""/></a:majorFont><a:minorFont><a:latin typeface="Aptos"/><a:ea typeface=""/><a:cs typeface=""/></a:minorFont></a:fontScheme><a:fmtScheme name="Simple"><a:fillStyleLst><a:solidFill><a:schemeClr val="phClr"/></a:solidFill><a:solidFill><a:schemeClr val="phClr"/></a:solidFill><a:solidFill><a:schemeClr val="phClr"/></a:solidFill></a:fillStyleLst><a:lnStyleLst><a:ln w="9525"><a:solidFill><a:schemeClr val="phClr"/></a:solidFill><a:prstDash val="solid"/></a:ln><a:ln w="9525"><a:solidFill><a:schemeClr val="phClr"/></a:solidFill><a:prstDash val="solid"/></a:ln><a:ln w="9525"><a:solidFill><a:schemeClr val="phClr"/></a:solidFill><a:prstDash val="solid"/></a:ln></a:lnStyleLst><a:effectStyleLst><a:effectStyle><a:effectLst/></a:effectStyle><a:effectStyle><a:effectLst/></a:effectStyle><a:effectStyle><a:effectLst/></a:effectStyle></a:effectStyleLst><a:bgFillStyleLst><a:solidFill><a:schemeClr val="phClr"/></a:solidFill><a:solidFill><a:schemeClr val="phClr"/></a:solidFill><a:solidFill><a:schemeClr val="phClr"/></a:solidFill></a:bgFillStyleLst></a:fmtScheme></a:themeElements></a:theme>'
 ct.append('<Override PartName="/ppt/theme/theme1.xml" ContentType="application/vnd.openxmlformats-officedocument.theme+xml"/>')
 for i,(title,seconds,speaker,bullets,notes,source) in enumerate(SLIDES,1):
  shapes=txt(2,650000,500000,10800000,950000,[title],3000,True)+txt(3,700000,1720000,10600000,3950000,['• '+b for b in bullets],2350)+txt(4,700000,5950000,10600000,550000,[source],1050,False,'526477')+txt(5,700000,6500000,10600000,200000,[f'BT4012 | Group XX | {i:02d}/{len(SLIDES)} | Speaker {speaker} | {seconds}s'],1000,False,'526477')
  parts[f'ppt/slides/slide{i}.xml']=XML+f'<p:sld {H}><p:cSld><p:bg><p:bgPr><a:solidFill><a:srgbClr val="FFFFFF"/></a:solidFill><a:effectLst/></p:bgPr></p:bg><p:spTree>{group()}{shapes}</p:spTree></p:cSld><p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:sld>'
  override(f'ppt/slides/slide{i}.xml','slide')
  parts[f'ppt/slides/_rels/slide{i}.xml.rels']=rels([('rId1','slideLayout','../slideLayouts/slideLayout1.xml')])
 parts['[Content_Types].xml']=XML+'<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'+''.join(ct)+'</Types>'
 with ZipFile(ppt,'w',ZIP_DEFLATED) as z:
  for name,body in parts.items(): ET.fromstring(body); z.writestr(name,body)
 elapsed=0
 lines=['# Presentation skeleton and speaker outline','','Draft, not submission-ready: replace Group XX and member placeholders. Rename the final deck presentationXX.pptx after confirming the group number. Target recording: **13:10**, including title and references; hard cap 15:00. A–D are provisional balanced sections for four speakers; reassign for actual group membership. Aesthetics and final recording remain outstanding.','', 'All slide text is editable. Figures listed below are source assets for the design pass; no unverified chart is invented. Speaker notes live in this outline, not embedded in the PPTX.','']
 for i,(title,seconds,speaker,bullets,notes,source) in enumerate(SLIDES,1):
  start=f'{elapsed//60:02d}:{elapsed%60:02d}'; elapsed+=seconds; end=f'{elapsed//60:02d}:{elapsed%60:02d}'
  lines.extend([f'## {i}. {title}', '', f'**Timing:** {start}–{end} ({seconds}s). **Speaker:** {speaker}.','']+[f'- {b}' for b in bullets]+['',f'**Speaking notes:** {notes}','',f'**Evidence / figure candidates:** {source}',''])
 lines.extend(['## Recording checklist','','- Replace group number, members and student IDs. Confirm names match the report.','- Rehearse all transitions and keep the actual recording under 15 minutes.','- Ensure every member speaks meaningfully and distribute time reasonably.','- Verify all numbers against generated evidence and keep exploratory labels visible.','- Add acknowledgements for any additional adopted external/AI-assisted material.','- Save final slides as presentationXX.pptx and recording as videoXX.mp4.','- Test video audio, readability and playback before submission.',''])
 (OUT/'slides.md').write_text('\n'.join(lines))
 receipt={'slides':len(SLIDES),'duration_seconds':elapsed,'timings_by_speaker':{s:sum(x[1] for x in SLIDES if x[2]==s) for s in 'ABCD'},'zip_xml_parts_checked':len(parts),'editable_text':True,'placeholders':['Group XX','member names and student IDs'],'application_open_verified':False}
 (OUT/'slide-validation.json').write_text(json.dumps(receipt,indent=2)+'\n')
 print(json.dumps(receipt,indent=2))
if __name__=='__main__': build()
